#include <stack>
#include <string>
#include <utility>

void safe_process(std::stack<std::string>& s) {
    if (s.empty()) return;

    // 1. Retrieve value (potentially using move semantics)
    std::string value = std::move(s.top()); 

    // 2. Remove the element (pop() returns void)
    s.pop(); 

    // value is now processed safely outside the stack
}
